// CATALOG.md is the page an agent reads instead of the source, generated by ui's own builder over
// this package's root (`buildCatalog(root, pattern, render)`), so one parser documents both. A
// stale page fails here until `bun run --filter @ultimat3/effects catalog` has run.

import { describe, expect, test } from 'bun:test';
// Relative, test-only: the builder is ui's tooling, not its public API.
import { buildCatalog, collectComponents } from '../../ui/src/catalog/build-catalog';
import { renderComponentsCatalog } from '../../ui/src/catalog/render-catalog';

const ROOT = Bun.fileURLToPath(new URL('..', import.meta.url)).replace(/\/$/, '');
const PATTERN = 'src/*/[A-Z]*.tsx';
const render = (docs: Parameters<typeof renderComponentsCatalog>[1]): string =>
  renderComponentsCatalog('@ultimat3/effects', docs);

describe('CATALOG.md', () => {
  test('matches what the current source renders', async () => {
    const committed = await Bun.file(`${ROOT}/CATALOG.md`).text();
    expect(committed).toBe(await buildCatalog(ROOT, PATTERN, render));
  });

  test('every entry is present with a purpose line and its props', async () => {
    const docs = await collectComponents(ROOT, PATTERN);
    expect(docs.map((doc) => doc.name)).toContain('ShaderBackground');
    expect(docs.filter((doc) => doc.summary === '').map((doc) => doc.name)).toEqual([]);
    expect(docs.filter((doc) => doc.props.length === 0).map((doc) => doc.name)).toEqual([]);
  });
});
